<?php

namespace App\Http\Controllers\Api\V1;

use App\Models\{AccountMapping, BankAccount, CompanyMembership, FiscalPeriod, Supplier, SupplierBankAccount, SupplierBill, SupplierCreditNote, SupplierPayment, SupplierPaymentAllocation, SupplierPaymentHold};
use App\Services\{AccountingService, AuditLogger, AuthorizationService};
use App\Support\{Decimal, TenantContext};
use Illuminate\Http\JsonResponse;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\ValidationException;

final class SupplierPaymentController
{
    public function index(Request $request, AuthorizationService $auth): JsonResponse
    {
        $tenant = $this->tenant(); $company = $request->string('company_id')->toString() ?: null; $this->scope($request, $auth, $tenant, $company);
        $query = SupplierPayment::where('tenant_id', $tenant)->with(['supplier', 'company', 'currency'])->when($company, fn ($q) => $q->where('company_id', $company))->when($request->filled('state'), fn ($q) => $q->where('state', $request->string('state')))->when($request->filled('search'), fn ($q) => $q->where('reference', 'ilike', '%'.$request->string('search').'%'))->latest('payment_date');
        return response()->json(['data' => $query->paginate(min(max($request->integer('per_page', 25), 10), 100))]);
    }

    public function store(Request $request, AuthorizationService $auth, AuditLogger $audit): JsonResponse
    {
        $tenant = $this->tenant(); $data = $request->validate(['company_id'=>'required|uuid','branch_id'=>'nullable|uuid','supplier_id'=>'required|uuid','bank_account_id'=>'nullable|uuid','supplier_bank_account_id'=>'nullable|uuid','currency_id'=>'required|uuid','reference'=>'required|string|max:100','method'=>'required|string|max:40','payment_date'=>'required|date','amount'=>['required','regex:/^\d+(\.\d{1,6})?$/'],'exchange_rate'=>['nullable','regex:/^\d+(\.\d{1,12})?$/'],'external_reference'=>'nullable|string|max:120','notes'=>'nullable|string|max:5000']); $this->scope($request, $auth, $tenant, $data['company_id']); abort_unless(Supplier::where('tenant_id',$tenant)->whereKey($data['supplier_id'])->exists(),404); if (! empty($data['bank_account_id'])) abort_unless(BankAccount::where('tenant_id',$tenant)->where('company_id',$data['company_id'])->where('status','active')->whereKey($data['bank_account_id'])->exists(),422,'The bank or cash account is not available for this company.'); if (! empty($data['supplier_bank_account_id'])) abort_unless(SupplierBankAccount::where('tenant_id',$tenant)->where('company_id',$data['company_id'])->where('supplier_id',$data['supplier_id'])->where('currency_id',$data['currency_id'])->where('verification_status','verified')->where('status','active')->whereKey($data['supplier_bank_account_id'])->exists(),422,'The supplier beneficiary is not verified and active.');
        $payment = SupplierPayment::create([...$data, 'tenant_id'=>$tenant, 'created_by'=>$request->user()->id, 'state'=>'draft', 'exchange_rate'=>$data['exchange_rate'] ?? '1']); $audit->record($request,'supplier_payment.created',$tenant,$payment); return response()->json(['data'=>$payment->load(['supplier','company','currency'])],201);
    }

    public function post(Request $request, SupplierPayment $supplierPayment, AccountingService $accounting, AuthorizationService $auth, AuditLogger $audit): JsonResponse
    {
        $tenant = $this->tenant(); abort_unless($supplierPayment->tenant_id === $tenant,404); $this->scope($request,$auth,$tenant,$supplierPayment->company_id); abort_unless($auth->allows($request->user(),$tenant,'accounting.post',$supplierPayment->company_id,$supplierPayment->branch_id),403); $payment = DB::transaction(function () use ($supplierPayment,$tenant,$request,$accounting): SupplierPayment { $payment=SupplierPayment::where('tenant_id',$tenant)->whereKey($supplierPayment->id)->lockForUpdate()->with(['bankAccount','supplierBankAccount'])->firstOrFail(); if($payment->state==='posted')return $payment; if($payment->state!=='draft'&&$payment->state!=='authorized')throw ValidationException::withMessages(['state'=>['Only draft or authorized payments can be posted.']]); if(!$payment->bank_account_id||!$payment->bankAccount)throw ValidationException::withMessages(['bank_account_id'=>['Select an authorized bank or cash account before posting.']]); if($payment->supplier_bank_account_id){if(!$payment->supplierBankAccount||$payment->supplierBankAccount->verification_status!=='verified'||$payment->supplierBankAccount->status!=='active')throw ValidationException::withMessages(['supplier_bank_account_id'=>['The supplier beneficiary is no longer verified and active.']]); if(SupplierPaymentHold::where('tenant_id',$tenant)->where('company_id',$payment->company_id)->where('supplier_id',$payment->supplier_id)->where('status','active')->where(fn($q)=>$q->whereNull('bank_account_id')->orWhere('bank_account_id',$payment->supplier_bank_account_id))->exists())throw ValidationException::withMessages(['payment'=>['An applicable supplier payment hold prevents posting this payment.']]); $payment->update(['beneficiary_snapshot'=>['supplier_bank_account_id'=>$payment->supplierBankAccount->id,'masked_reference'=>$payment->supplierBankAccount->masked_reference,'bank_name'=>$payment->supplierBankAccount->bank_name,'verified_at'=>$payment->supplierBankAccount->verified_at?->toIso8601String()]]); } $ap=AccountMapping::where('tenant_id',$tenant)->where('company_id',$payment->company_id)->where('mapping_key','accounts_payable')->first(); if(!$ap)throw ValidationException::withMessages(['accounting'=>['Configure the company accounts_payable account mapping before posting payments.']]); $period=FiscalPeriod::where('tenant_id',$tenant)->whereHas('fiscalYear',fn($q)=>$q->where('company_id',$payment->company_id))->whereDate('starts_on','<=',$payment->payment_date)->whereDate('ends_on','>=',$payment->payment_date)->first(); if(!$period)throw ValidationException::withMessages(['payment_date'=>['No open fiscal period is configured for this payment date.']]); $entry=$accounting->post(['tenant_id'=>$tenant,'company_id'=>$payment->company_id,'fiscal_period_id'=>$period->id,'currency_id'=>$payment->currency_id,'created_by'=>$request->user()->id,'entry_date'=>$payment->payment_date->toDateString(),'source_type'=>SupplierPayment::class,'source_id'=>$payment->id,'idempotency_key'=>'supplier-payment:'.$payment->id,'exchange_rate'=>$payment->exchange_rate,'description'=>'Supplier payment '.$payment->reference,'lines'=>[['account_id'=>$ap->account_id,'debit'=>$payment->amount,'credit'=>'0','description'=>'Accounts payable settlement'],['account_id'=>$payment->bankAccount->ledger_account_id,'debit'=>'0','credit'=>$payment->amount,'description'=>'Supplier payment']]]); $payment->update(['state'=>'posted','posted_by'=>$request->user()->id,'posted_at'=>now(),'accounting_entry_id'=>$entry->id,'posting_idempotency_key'=>'supplier-payment:'.$payment->id]); return $payment->fresh(); }); $audit->record($request,'supplier_payment.posted',$tenant,$payment); return response()->json(['data'=>$payment]);
    }

    public function allocate(Request $request, SupplierPayment $supplierPayment, AuthorizationService $auth, AuditLogger $audit): JsonResponse
    {
        $tenant=$this->tenant(); abort_unless($supplierPayment->tenant_id===$tenant,404); $this->scope($request,$auth,$tenant,$supplierPayment->company_id); abort_unless($supplierPayment->state==='posted',422,'Only posted payments can be allocated.'); $data=$request->validate(['bill_id'=>'required|uuid','amount'=>['required','regex:/^\d+(\.\d{1,6})?$/']]); $allocation=DB::transaction(function()use($supplierPayment,$data,$tenant):SupplierPaymentAllocation{$payment=SupplierPayment::where('tenant_id',$tenant)->whereKey($supplierPayment->id)->lockForUpdate()->firstOrFail();$bill=SupplierBill::where('tenant_id',$tenant)->whereKey($data['bill_id'])->lockForUpdate()->firstOrFail();abort_unless($bill->state==='posted'&&$bill->company_id===$payment->company_id&&$bill->supplier_id===$payment->supplier_id&&$bill->currency_id===$payment->currency_id,422,'Payment and bill must be posted for the same supplier, company, and currency.');$amount=Decimal::normalize((string)$data['amount']);$used=SupplierPaymentAllocation::where('tenant_id',$tenant)->where('supplier_payment_id',$payment->id)->sum('amount');$billUsed=SupplierPaymentAllocation::where('tenant_id',$tenant)->where('supplier_bill_id',$bill->id)->sum('amount');$remainingPayment=Decimal::sub((string)$payment->amount,(string)$used);$remainingBill=Decimal::sub((string)$bill->grand_total,(string)$billUsed);if(Decimal::compare($amount,$remainingPayment)>0||Decimal::compare($amount,$remainingBill)>0)throw ValidationException::withMessages(['amount'=>['Allocation exceeds the posted payment or open bill balance.']]);return SupplierPaymentAllocation::create(['tenant_id'=>$tenant,'supplier_payment_id'=>$payment->id,'supplier_bill_id'=>$bill->id,'amount'=>$amount]);}); $audit->record($request,'supplier_payment.allocated',$tenant,$allocation); return response()->json(['data'=>$allocation],201);
    }

    public function payable(Request $request, AuthorizationService $auth): JsonResponse
    {
        $tenant=$this->tenant();$company=$request->string('company_id')->toString()?:null;$this->scope($request,$auth,$tenant,$company);$bills=SupplierBill::where('tenant_id',$tenant)->where('state','posted')->with(['supplier','company','branch'])->when($company,fn($q)=>$q->where('company_id',$company))->when($request->filled('supplier_id'),fn($q)=>$q->where('supplier_id',$request->string('supplier_id')))->when($request->filled('due_before'),fn($q)=>$q->whereDate('due_date','<=',$request->date('due_before')))->latest('due_date')->paginate(min(max($request->integer('per_page',25),10),100));$rows=$bills->getCollection()->map(function($bill){$allocated=(string)SupplierPaymentAllocation::where('supplier_bill_id',$bill->id)->whereHas('payment',fn($q)=>$q->where('state','posted'))->sum('amount');$credits=(string)SupplierCreditNote::where('supplier_bill_id',$bill->id)->where('state','posted')->sum('total');$open=Decimal::sub(Decimal::sub((string)$bill->grand_total,$allocated),$credits);$due=$bill->due_date?->toDateString();$bucket=!$due||$due>=now()->toDateString()?'current':(now()->diffInDays($bill->due_date)<=30?'1_30':(now()->diffInDays($bill->due_date)<=60?'31_60':(now()->diffInDays($bill->due_date)<=90?'61_90':'over_90')));return ['id'=>$bill->id,'bill_number'=>$bill->number,'supplier'=>$bill->supplier?->name,'company'=>$bill->company?->name,'branch'=>$bill->branch?->name,'invoice_date'=>$bill->invoice_date?->toDateString(),'due_date'=>$due,'currency_code'=>$bill->currency_code,'original_amount'=>(string)$bill->grand_total,'allocated_amount'=>$allocated,'supplier_credits'=>$credits,'outstanding_balance'=>$open,'aging_bucket'=>$bucket,'payment_status'=>Decimal::compare($open,'0')<=0?'paid':($bucket==='current'?'open':'overdue')];});$bills->setCollection($rows);return response()->json(['data'=>$bills]);
    }

    private function scope(Request $request, AuthorizationService $auth, string $tenant, ?string $company): void { if($company){abort_unless($auth->allows($request->user(),$tenant,'procurement.manage',$company)||$auth->allows($request->user(),$tenant,'accounting.post',$company),403);abort_unless(CompanyMembership::where('tenant_id',$tenant)->where('company_id',$company)->where('user_id',$request->user()->id)->where('status','active')->exists(),403);}}
    private function tenant(): string{return (string)app(TenantContext::class)->id();}
}
